                "required": ["path"],
                "properties": {
                  "path": {"type": "string", "description": "目录/模块路径（尽量与 dir_loc 的 dir 对齐；子目录拆分时在 reason 说明估算依据）。字段名必须为 path，不是 dir/module/name"},
                  "loc": {"type": "integer"},
                  "reason": {"type": "string", "description": "中文：为何归入此桶（GUI 层重写/含 Win32 调用点/纯算法…）；unadaptable 模块引用 ua:* id 而不重述。字段名必须为 reason，不是 note"},
                  "evidence": {"type": "array", "items": {"type": "string"},
                    "description": "复用来源维度的 file:line（native_api 调用点/platform_branches samples 等，代表性）"}}}},
              "basis": {"type": "string", "description": "中文：本桶归类依据（引用了哪些机械信号/维度证据）"}}}},
        "notes": {"type": "string", "description": "中文：未覆盖长尾、估算口径、局限"}
